// Typed API access. Response/entity types come from src/api/schema.d.ts,
// generated by `npm run gen:api` from the server's OpenAPI — CI fails on drift.

import type { components } from './schema';

export type Paper = components['schemas']['Paper'];
export type Review = components['schemas']['Review'];
export type ReproductionSummary = components['schemas']['ReproductionSummary'];
export type ReproduceRun = components['schemas']['ReproduceRun'];
export type ApiKeyCreated = components['schemas']['ApiKeyCreated'];
export type ApiKeyMeta = components['schemas']['ApiKeyMeta'];
export type Thread = components['schemas']['Thread'];
export type Post = components['schemas']['Post'];

// Categories are seed data; the list endpoint carries no body schema yet.
export interface Category {
  id: string;
  slug: string;
  name: string;
  description: string;
  created_at: string;
}

// The uniform list envelope (automl-core::Page<T>).
export interface Page<T> {
  data: T[];
  next_cursor: string | null;
}

export class ApiError extends Error {
  code: string;
  status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.code = code;
    this.status = status;
  }
}

export async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const resp = await fetch(path, {
    credentials: 'include',
    headers: init?.body ? { 'content-type': 'application/json' } : undefined,
    ...init,
  });
  if (resp.status === 204) return undefined as T;
  const text = await resp.text();
  if (!resp.ok) {
    let code = 'HTTP_ERROR';
    let message = `HTTP ${resp.status}`;
    try {
      const v = JSON.parse(text);
      code = v?.error?.code ?? code;
      message = v?.error?.message ?? message;
    } catch {
      /* non-JSON error body — keep fallback */
    }
    throw new ApiError(code, message, resp.status);
  }
  return text ? (JSON.parse(text) as T) : (undefined as T);
}

export function loginHref(): string {
  const next = window.location.pathname + window.location.search;
  return `/auth/login?next=${encodeURIComponent(next)}`;
}
